class Employee { private int employeeId; private String employeeName; private double salary; static int employeeCount; protected String department="Pharmacy"; Employee(int employeeId,String employeeName,double salary){this.employeeId=employeeId;this.employeeName=employeeName;setSalary(salary);employeeCount++;} public int getEmployeeId(){return employeeId;} public String getEmployeeName(){return employeeName;} public double getSalary(){return salary;} public void setSalary(double salary){if(salary>=0)this.salary=salary;} void printDepartment(){System.out.println(department);} }
class Pharmacist extends Employee { private String licenseNo; Pharmacist(int id,String n,double s,String l){super(id,n,s);this.licenseNo=l;} void display(){System.out.println(getEmployeeName()+" Pharmacist "+licenseNo+" "+getSalary());} }
class StoreManager extends Employee { private int storeSection; StoreManager(int id,String n,double s,int section){super(id,n,s);this.storeSection=section;} void display(){System.out.println(getEmployeeName()+" Store Manager section "+storeSection+" "+getSalary());} }
class EmployeeManager { void process(Employee[] employees){int total=0;for(Employee e:employees){if(e instanceof Pharmacist)((Pharmacist)e).display();else if(e instanceof StoreManager)((StoreManager)e).display();if(e.getSalary()>=0)total++;}System.out.println("Valid employees: "+total);} }
public class Q20_PharmacyEmployeeMain { public static void main(String[] a){Employee[] e={new Pharmacist(1,"Asha",50000,"LIC1"),new StoreManager(2,"Ravi",60000,3)};new EmployeeManager().process(e);} }
